...
}

3.
@WebMethod
public List<Rb_stat> getStatList(@WebParam(name = "inputObject", targetNamespace = "http://rb.lite.ws.daisy.marbes.cz") @XmlParamType(name = "DOlrb_stat") Rb_stat inputObject {
