A client is invoking a soap 1.2 .NET webservice. The issue we're having is that the remote service requires soap action headers and cxf's wsdl2java is not generating action parameters for each WebMethod annotation automatically. 

For example, wsdl2java will generate this annotation:

@WebMethod(operationName = "GetCustomerData")

but we need it to generate this one:

@WebMethod(operationName = "GetCustomerData",action = "http://tempuri.org/IAceRewardsService/GetCustomerData")

public Server create() {
try {
applyExtraClass();
if (serviceBean != null && getServiceClass() == null) {
setServiceClass(ClassHelper.getRealClass(serviceBean));
}
if (invoker != null) {
getServiceFactory().setInvoker(invoker);
} else if (serviceBean != null) {
// we should set the invoker here
getServiceFactory().setInvoker(createInvoker()); 
}

Endpoint ep = createEndpoint();
server = new ServerImpl(getBus(),
ep,
getDestinationFactory(),
getBindingFactory());

if (ep.getService().getInvoker() == null) {
if (invoker == null) {
ep.getService().setInvoker(createInvoker());
} else {
ep.getService().setInvoker(invoker);
}
}

if (start) {
server.start();
}
} catch (EndpointException e) {
throw new ServiceConstructionException(e);
} catch (BusException e) {
throw new ServiceConstructionException(e);
} catch (IOException e) {
throw new ServiceConstructionException(e);
}

if (serviceBean != null) {
initializeAnnotationInterceptors(server.getEndpoint(),
ClassHelper.getRealClass(getServiceBean()));
} else if (getServiceClass() != null) {
initializeAnnotationInterceptors(server.getEndpoint(), getServiceClass());
}


applyFeatures();
return server;
}

