public class TestFaultThrowingInterceptor extends AbstractPhaseInterceptor<Message> { 

public TestFaultThrowingInterceptor() { 
super(Phase.UNMARSHAL); 
addAfter(URIMappingInterceptor.class.getName()); 
addBefore( 
