AlgorithmSuite suite = loader.getAlgorithmSuite(algoSuiteName, consts); 
if(suite == null) { 
throw new IllegalArgumentException("Algorithm suite \"" + algoSuiteName + "\" is not registered"); 
} 

return suite; 
} 

public QName[] getKnownElements() { 
