{code} 
@Path("invoice/") 
@Consumes(MediaType.APPLICATION_XML) 
@Produces(MediaType.APPLICATION_XML) 
public interface InvoiceWebservice { 
@POST 
public void insert(WSInvoice wsInvoice); 

[...] 
