This small test: 

{code:java} 
@Test 
public void should_read_entity() { 
final String str = "ouch"; 

Response response = Response.status(Response.Status.INTERNAL_SERVER_ERROR) 
.entity(str) 
.build(); 
Assert.assertEquals(str, response.readEntity(String.class)); 
} 
