? ((FileInputStream)fis).getChannel() : Channels.newChannel(fis); 
buffer = ByteBuffer.allocate(8 * 1024); 
} 
} 
int i = -1; 
buffer.rewind(); 
if (buffer.hasRemaining() && chan != null) { 
i = chan.read(buffer); 
buffer.flip(); 
} 
enc.write(buffer); 
